// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/login", wrapper.PostAuthLogin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/logout", wrapper.PostAuthLogout)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/logout/all", wrapper.PostAuthLogoutAll)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/quick-connect/poll", wrapper.PostAuthQuickConnectPoll)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/quick-connect/start", wrapper.PostAuthQuickConnectStart)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/refresh", wrapper.PostAuthRefresh)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/healthz", wrapper.GetHealthz)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/home", wrapper.GetHome)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/library", wrapper.GetLibrary)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/library/{id}", wrapper.GetLibraryId)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/library/{id}/request", wrapper.PostLibraryIdRequest)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/library/{id}/seasons/{seasonNumber}/episodes", wrapper.GetLibraryIdSeasonsSeasonNumberEpisodes)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/playback/{id}/progress", wrapper.PutPlaybackIdProgress)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/search", wrapper.GetSearch)

	return m
}

